from pathlib import Path
import hashlib,json,shutil
lab=Path('F:/Projects/tyrax2-lab-20261001');base=lab/'arena-check-night'
dst=lab/'pipeline-attribution';assert not dst.exists()
shutil.copytree(base/'tyra',dst/'tyra',ignore=shutil.ignore_patterns('obj','*.log'))
shutil.copytree(base/'game',dst/'game',ignore=shutil.ignore_patterns('obj','*.log','*.elf','*.elf.sym','*.p2s','ps2link.run'))
header=r'''// Modified by TyraX: scratch diagnostic, no new waits or GPU hold.
#pragma once
#include <cstdio>
#include "debug/frame_profile.hpp"
namespace Tyra { namespace PipelineAttrib {
inline unsigned long long ticks[6]={};
inline unsigned calls[6]={};
struct Scope {
 unsigned i,begin;
 explicit Scope(unsigned index):i(index),begin(FrameProfile::ticks()){}
 ~Scope(){ticks[i]+=unsigned(FrameProfile::ticks()-begin);++calls[i];}
};
inline void report(unsigned f){
 static unsigned prev=0;
 if(!f || f%50 || prev==f)return;
 const unsigned n=f-prev;prev=f;
 printf("LOG: PIPEATTR f=%u n=%u vifWait=%.5f finishWait=%.5f cache=%.5f snapshot=%.5f convert=%.5f submit=%.5f calls=%u/%u/%u/%u/%u/%u\n",
 f,n,float(ticks[0])/294912/n,float(ticks[1])/294912/n,float(ticks[2])/294912/n,
 float(ticks[3])/294912/n,float(ticks[4])/294912/n,float(ticks[5])/294912/n,
 calls[0],calls[1],calls[2],calls[3],calls[4],calls[5]);
 for(unsigned i=0;i<6;++i){ticks[i]=0;calls[i]=0;}
}
}}
'''
(dst/'tyra/engine/inc/debug/pipeline_attribution.hpp').write_bytes(header.encode())
def edit(p,old,new):
 s=p.read_text(encoding='utf-8');assert s.count(old)==1,(p,old,s.count(old));p.write_bytes(s.replace(old,new).encode())
rc=dst/'tyra/engine/src/renderer/core/renderer_core.cpp'
q=dst/'tyra/engine/src/renderer/core/paths/path1/vif1_queue.cpp'
for p in [rc,q]:p.write_bytes(('#include "debug/pipeline_attribution.hpp"\n'+p.read_text(encoding='utf-8')).encode())
edit(rc,'  Vif1Queue::waitFor(pipelineSequence);','  { PipelineAttrib::Scope timing(0); Vif1Queue::waitFor(pipelineSequence); }')
# Only the existing final FINISH wait inside pipeline completion, not unrelated syncs.
edit(rc,'  sync.waitAndClear();\n  u32 t0, t1;','  { PipelineAttrib::Scope timing(1); sync.waitAndClear(); }\n  u32 t0, t1;')
edit(q,'    FlushCache(0);\n    flushedUpTo = submitted;','    { PipelineAttrib::Scope timing(2); FlushCache(0); }\n    flushedUpTo = submitted;')
edit(q,'u32 Vif1Queue::submit(const void* chain, u32 qwords, bool* sourceCopied) {','u32 Vif1Queue::submit(const void* chain, u32 qwords, bool* sourceCopied) {\n  PipelineAttrib::Scope submissionTiming(5);')
edit(q,'  if (chainArena) {\n    auto snapshot = chainArena->copy(chain,','  if (chainArena) {\n    PipelineAttrib::Scope snapshotTiming(3);\n    auto snapshot = chainArena->copy(chain,')
edit(q,'      sourceCopied && *sourceCopied) {\n    u32 records = 0;','      sourceCopied && *sourceCopied) {\n    PipelineAttrib::Scope conversionTiming(4);\n    u32 records = 0;')
p=dst/'game/src/terrain_game.cpp'
p.write_bytes(('#include "debug/pipeline_attribution.hpp"\n'+p.read_text(encoding='utf-8')).encode())
edit(p,'void TerrainGame::loop() {','void TerrainGame::loop() {\n  Tyra::PipelineAttrib::report(ftrig::frame);')
paths=[dst/'tyra/engine/inc/debug/pipeline_attribution.hpp',rc,q,p]
meta={'scope':'Existing wait/cache/snapshot/conversion brackets only, no new waits, no GPU-hold; inclusive nested diagnostic timings, not VU/GS utilization.', 'first':1100,'frames':512,'engine':str(dst/'tyra'),'artifacts':{str(p.relative_to(dst)):hashlib.sha256(p.read_bytes()).hexdigest() for p in paths}}
(dst/'fixture.json').write_bytes((json.dumps(meta,indent=2)+'\n').encode())
print('Private diagnostic engine/game prepared')

