from pathlib import Path
import hashlib,json
root=Path('F:/Projects/tyrax2-lab-20261001/pipeline-attribution')
def edit(p,old,new):
 s=p.read_text(encoding='utf-8');assert s.count(old)==1,(p,old,s.count(old));p.write_bytes(s.replace(old,new).encode())
h=root/'tyra/engine/inc/debug/pipeline_attribution.hpp'
edit(h,'#include <cstdio>','#include <cstdio>\n#include <gs_privileged.h>')
edit(h,'inline unsigned long long ticks[6]={};\ninline unsigned calls[6]={};',r'''inline unsigned long long ticks[7]={};
inline unsigned calls[7]={};
inline unsigned nextSequence=0, started=0, poll=0, missed=0;
inline bool tracking=false;
inline void beginIfSequence(unsigned sequence){
 if(sequence!=nextSequence || !nextSequence)return;
 if(tracking)++missed;
 nextSequence=0;started=FrameProfile::ticks();tracking=true;poll=0;
}
inline void finishObserved(){
 if(!tracking)return;
 ticks[6]+=unsigned(FrameProfile::ticks()-started);++calls[6];tracking=false;
}
inline void observeFinish(bool force=false){
 if(!tracking)return;
 if(!force && (++poll&7))return;
 if(*GS_REG_CSR&2)finishObserved();
}''')
edit(h,'submit=%.5f calls=%u/%u/%u/%u/%u/%u\\n','submit=%.5f consumerObserved=%.5f samples=%u missed=%u calls=%u/%u/%u/%u/%u/%u\\n')
edit(h,'float(ticks[3])/294912/n,float(ticks[4])/294912/n,float(ticks[5])/294912/n,','float(ticks[3])/294912/n,float(ticks[4])/294912/n,float(ticks[5])/294912/n,\n float(ticks[6])/294912/n,calls[6],missed,')
edit(h,'for(unsigned i=0;i<6;++i){ticks[i]=0;calls[i]=0;}','for(unsigned i=0;i<7;++i){ticks[i]=0;calls[i]=0;}\n missed=0;')
q=root/'tyra/engine/src/renderer/core/paths/path1/vif1_queue.cpp'
edit(q,'  *kChcr = kChainChcr;','  PipelineAttrib::beginIfSequence(sequence);\n  *kChcr = kChainChcr;')
edit(q,'  PipelineAttrib::Scope submissionTiming(5);','  PipelineAttrib::observeFinish();\n  PipelineAttrib::Scope submissionTiming(5);')
edit(q,'  enqueue(nativeWriter->data(), sequence);','  if(framePipelined && !frameRecording) PipelineAttrib::nextSequence=sequence;\n  enqueue(nativeWriter->data(), sequence);')
rc=root/'tyra/engine/src/renderer/core/renderer_core.cpp'
edit(rc,'  { PipelineAttrib::Scope timing(0); Vif1Queue::waitFor(pipelineSequence); }','  PipelineAttrib::observeFinish(true);\n  { PipelineAttrib::Scope timing(0); Vif1Queue::waitFor(pipelineSequence); }')
edit(rc,'  { PipelineAttrib::Scope timing(1); sync.waitAndClear(); }','  { PipelineAttrib::Scope timing(1); sync.waitAndClear(); }\n  PipelineAttrib::finishObserved();')
p=root/'fixture.json';d=json.loads(p.read_text());d['observer_note']='Read-only GS FINISH sampled every eighth submit and before existing completion; timestamp from final-prefix VIF1 start to first observation is an upper bound for combined consumer completion, not VU-only duration. No extra wait or bit clear. samples=50 and missed=0 required per warm window.'
for f in [h,q,rc]:d['artifacts'][str(f.relative_to(root))]=hashlib.sha256(f.read_bytes()).hexdigest()
p.write_bytes((json.dumps(d,indent=2)+'\n').encode());print('Read-only FINISH observation added')
